begin;
do $$
declare
  p record; tube bigint; tube2 bigint; lot1 bigint; lot2 bigint; u record;
begin
  select * into p from test_places();
  tube := register_container('tube_1_5ml', '2026-09-01 10:00', 'p:lena', 'TGT-0001', p_into => p.freezer);
  lot1 := receive('vendorA:EGFR-100', tube, 500, 'volume', '2026-09-01 10:00', 'p:lena',
                  p_supplier_lot => 'L4471', p_ref => 'delivery:DN-9001', p_price => 300);

  -- Arrived, but nobody has checked it yet: we hold 500 µL and can use none of it.
  select * into u from usable('2026-09-01 12:00') where container_id = tube;
  perform expect(u.held, 500::numeric, 'held after arrival');
  perform expect(u.usable, 0::numeric, 'usable before QC');
  perform expect(u.reasons, array['waiting for QC'], 'reasons before QC');

  -- QC passes the next day. Now it's usable, minus the 5 µL a pipette can't reach.
  perform qc(lot1, 'pass', 'SDS-PAGE and concentration', '2026-09-02 09:00', 'p:marco');
  select * into u from usable('2026-09-02 12:00') where container_id = tube;
  perform expect(u.usable, 495::numeric, 'usable after QC pass');

  -- Looking back at yesterday still says "waiting for QC".
  select * into u from usable('2026-09-01 12:00') where container_id = tube;
  perform expect(u.reasons, array['waiting for QC'], 'yesterday, seen from today');

  -- A second delivery of the same supplier lot is a new batch and waits for its own QC (decision D2).
  tube2 := register_container('tube_1_5ml', '2026-09-20 10:00', 'p:lena', 'TGT-0002', p_into => p.freezer);
  lot2 := receive('vendorA:EGFR-100', tube2, 500, 'volume', '2026-09-20 10:00', 'p:lena',
                  p_supplier_lot => 'L4471', p_ref => 'delivery:DN-9377');
  perform expect_true(lot2 <> lot1, 'second delivery is its own batch');
  select * into u from usable('2026-09-20 12:00') where container_id = tube2;
  perform expect(u.reasons, array['waiting for QC'], 'second delivery of a checked lot');

  -- It fails. It still exists, and the record says exactly why it can't be used.
  perform qc(lot2, 'fail', 'SDS-PAGE and concentration', '2026-09-21 09:00', 'p:marco', '{"concentration_mg_ml": 0.21}');
  select * into u from usable('2026-09-21 12:00') where container_id = tube2;
  perform expect(u.held, 500::numeric, 'failed lot is still held');
  perform expect(u.reasons, array['failed QC'], 'reasons after QC fail');
end $$;
rollback;

begin;
do $$
declare
  p record; stock bigint; box bigint; lot1 bigint; kids bigint[]; total numeric; u record;
begin
  select * into p from test_places();
  stock := register_container('tube_1_5ml', '2026-09-01 10:00', 'p:lena', 'TGT-0001', p_into => p.freezer);
  lot1 := receive('vendorA:EGFR-100', stock, 500, 'volume', '2026-09-01 10:00', 'p:lena', p_supplier_lot => 'L4471');
  perform qc(lot1, 'pass', 'SDS-PAGE', '2026-09-02 09:00', 'p:marco');

  -- Thawed on the bench, split into 20 tubes of 24 µL, which go into a box in the freezer.
  perform move(stock, p.bench, null, '2026-09-03 09:00', 'p:marco');
  box := register_container('box_9x9', '2026-09-03 09:30', 'p:marco', 'BOX-0007', p_into => p.freezer);
  kids := split(stock, lot1, 20, 24, 'tube_matrix', '2026-09-03 09:30', 'p:marco', 'ALQ-', p_into => box);
  perform move(stock, p.freezer, null, '2026-09-03 09:40', 'p:marco');

  perform expect(cardinality(kids), 20, 'number of aliquots');

  -- Every aliquot carries the same lot, so it also carries the QC pass.
  perform expect((select count(distinct lot_id) from balances('2026-09-03 10:00') where container_id = any(kids)), 1::bigint, 'one lot across aliquots');
  perform expect((select count(*) from usable('2026-09-03 10:00') where container_id = any(kids) and cardinality(reasons) = 0), 20::bigint, 'all aliquots usable');

  -- Nothing appeared out of thin air: 480 µL in the aliquots, 20 µL left in the stock tube.
  select sum(held) into total from usable('2026-09-03 10:00') where lot_id = lot1;
  perform expect(total, 500::numeric, 'total held across stock and aliquots');
  select * into u from usable('2026-09-03 10:00') where container_id = stock;
  perform expect(u.held, 20::numeric, 'left in the stock tube');
  perform expect(u.usable, 15::numeric, 'usable in the stock tube, minus 5 µL dead volume');

  -- Each aliquot holds 24 µL but 10 µL is stuck at the bottom of a matrix tube.
  perform expect((select sum(usable) from usable('2026-09-03 10:00') where container_id = any(kids)), 280::numeric, 'usable across aliquots');

  -- The stock tube was thawed once before the split, so the aliquots inherit one thaw.
  perform expect((select max(thaws) from usable('2026-09-03 10:00') where container_id = any(kids)), 1::bigint, 'thaws inherited by aliquots');

  -- Each aliquot can be found: box, slot, freezer.
  perform expect((select path from location('2026-09-03 10:00') where container_id = kids[7]),
                 'Freezer F1 > BOX-0007 @slot 7', 'location of aliquot 7');
end $$;
rollback;

begin;
do $$
declare
  p record; tube bigint; lot1 bigint; bad bigint; fix bigint; u record;
begin
  select * into p from test_places();
  tube := register_container('tube_1_5ml', '2026-09-01 10:00', 'p:lena', 'TGT-0001', p_into => p.freezer);
  lot1 := receive('vendorA:EGFR-100', tube, 100, 'volume', '2026-09-01 10:00', 'p:lena', p_supplier_lot => 'L4471');
  perform qc(lot1, 'pass', 'SDS-PAGE', '2026-09-02 09:00', 'p:marco');

  -- Monday: Marco takes 80 µL, but types 30 (an extra zero lost the other way round happens too).
  bad := consume(tube, lot1, 30, 'volume', '2026-09-07 10:00', 'p:marco');
  -- Tuesday: Lena takes 75 µL. The record says only 70 is there.
  perform consume(tube, lot1, 75, 'volume', '2026-09-08 10:00', 'p:lena');

  -- Decision D1: we don't refuse. The balance goes negative, it's flagged, and nothing in the tube counts as usable.
  select * into u from usable('2026-09-08 12:00') where container_id = tube;
  perform expect(u.held, -5::numeric, 'balance after overdraw');
  perform expect_true('negative balance' = any(u.reasons), 'negative balance blocks use');
  perform expect((select count(*) from flags('2026-09-08 12:00') where flag = 'negative balance' and container_id = tube), 1::bigint, 'flag raised');

  -- Thursday: Marco checks his notebook. It was 80, not 30. He records a correction.
  fix := void(bad, 'p:marco', 'Typed 30, notebook says 80', '2026-09-10 16:00');
  perform consume(tube, lot1, 80, 'volume', '2026-09-07 10:00', 'p:marco', p_event => fix);

  -- Now Tuesday's draw looks impossible instead (only 20 was left), and that is the truth.
  select * into u from usable('2026-09-08 12:00') where container_id = tube;
  perform expect(u.held, -55::numeric, 'Tuesday, as we know it now');

  -- But what did the system say on Tuesday evening? Exactly what it said then.
  select * into u from usable('2026-09-08 18:00', '2026-09-08 18:00') where container_id = tube;
  perform expect(u.held, -5::numeric, 'Tuesday, as we knew it on Tuesday');

  -- The old entry is still there, marked as corrected, with who and why.
  perform expect((select count(*) from event where id = bad), 1::bigint, 'original entry kept');
  perform expect((select note from event where voids_event_id = bad), 'Typed 30, notebook says 80', 'reason for the correction');

  -- Lena admits she took 15, not 75. Her correction makes the books balance.
  fix := void((select e.id from event e join quantity_entry q on q.event_id = e.id
               where q.container_id = tube and q.amount = -75), 'p:lena', 'Took 15, typed 75', '2026-09-11 09:00');
  perform consume(tube, lot1, 15, 'volume', '2026-09-08 10:00', 'p:lena', p_event => fix);
  select * into u from usable('2026-09-11 12:00') where container_id = tube;
  perform expect(u.held, 5::numeric, 'balance after both corrections');
  perform expect((select count(*) from flags('2026-09-11 12:00') where flag = 'negative balance'), 0::bigint, 'flag gone');

  -- A correction can be corrected too: undoing Lena's fix brings the old numbers back.
  perform void(fix, 'p:sara', 'Lena''s fix was entered on the wrong tube', '2026-09-12 09:00');
  select * into u from usable('2026-09-12 12:00') where container_id = tube;
  perform expect(u.held, -55::numeric, 'after the correction is corrected');

  -- Facts can't be edited or deleted.
  perform expect_error(format('update quantity_entry set amount = -1 where event_id = %s', bad), 'append-only', 'editing a fact');
  perform expect_error(format('delete from event where id = %s', bad), 'append-only', 'deleting a fact');
end $$;
rollback;

begin;
do $$
declare
  p record; tube1 bigint; tube2 bigint; lot1 bigint; lot2 bigint; fix bigint;
begin
  select * into p from test_places();

  -- Lena registers the box at the door from the packing slip.
  tube1 := register_container('tube_1_5ml', '2026-09-14 09:00', 'p:lena', 'TGT-0101', p_into => p.freezer);
  lot1 := receive('vendorA:EGFR-100', tube1, 400, 'volume', '2026-09-14 09:00', 'p:lena',
                  p_supplier_lot => 'B1102', p_ref => 'delivery:DN-1102');

  -- The import job times out and sends the same delivery note again. One real
  -- delivery can only be counted once, so the database says no.
  perform expect_error(
    format('select receive(%L, %s, 400, %L, %L, %L, p_supplier_lot => %L, p_ref => %L)',
           'vendorA:EGFR-100', tube1, 'volume', '2026-09-14 09:05', 'system:import', 'B1102', 'delivery:DN-1102'),
    'duplicate key', 'registering the same delivery note twice');
  perform expect((select count(*) from lot where product_id = 'vendorA:EGFR-100'), 1::bigint, 'lots after the refused retry');

  -- Marco unpacks the same box at the freezer and registers it again, scanning
  -- a fresh tube. He has no delivery note in hand, so the reference is his own.
  tube2 := register_container('tube_1_5ml', '2026-09-14 11:00', 'p:marco', 'TGT-0102', p_into => p.freezer);
  lot2 := receive('vendorA:EGFR-100', tube2, 400, 'volume', '2026-09-14 11:00', 'p:marco',
                  p_supplier_lot => 'B1102', p_ref => 'unpack:marco-0914-1');

  -- That gets through, but it looks like the first one: same product, same
  -- supplier lot, same amount, two hours apart.
  perform expect((select count(*) from flags('2026-09-14 12:00', '2026-09-14 12:00')
                  where flag = 'possible duplicate delivery' and lot_id = lot2), 1::bigint, 'duplicate delivery flag');
  perform expect((select sum(held) from usable('2026-09-14 12:00', '2026-09-14 12:00') where material_id = 'target:egfr'),
                 800::numeric, 'held while the double entry stands');

  -- Next morning Sara voids Marco's registration, and the tube he registered with it.
  fix := void((select created_event_id from lot where id = lot2), 'p:sara',
              'Same box registered twice, once at the door and once at the freezer', '2026-09-15 10:00');
  perform void((select created_event_id from container where id = tube2), 'p:sara',
               'Ghost tube from the double registration', '2026-09-15 10:00');

  -- The flag and the extra 400 µL are gone, and so is the ghost tube.
  perform expect((select count(*) from flags('2026-09-15 12:00', '2026-09-15 12:00')
                  where flag = 'possible duplicate delivery'), 0::bigint, 'flag after the correction');
  perform expect((select sum(held) from usable('2026-09-15 12:00', '2026-09-15 12:00') where material_id = 'target:egfr'),
                 400::numeric, 'held after the correction');
  perform expect((select count(*) from balances('2026-09-15 12:00', '2026-09-15 12:00') where container_id = tube2),
                 0::bigint, 'nothing left in the ghost tube');
  perform expect((select count(*) from location('2026-09-15 12:00', '2026-09-15 12:00') where container_id = tube2),
                 0::bigint, 'ghost tube no longer listed');

  -- Asked what the system said on the 14th, it still says 800.
  perform expect((select sum(held) from usable('2026-09-14 12:00', '2026-09-14 12:00') where material_id = 'target:egfr'),
                 800::numeric, 'what we believed on the 14th');

  -- Nothing was deleted: the lot, its event and the reason for undoing it are all on record.
  perform expect((select count(*) from lot where id = lot2), 1::bigint, 'voided lot still on record');
  perform expect((select note from event where id = fix), 'Same box registered twice, once at the door and once at the freezer',
                 'reason for the correction');
end $$;
rollback;

begin;
do $$
declare
  p record; old_plate bigint; other_plate bigint; new_plate bigint; t1 bigint; t2 bigint; hepes bigint;
begin
  select * into p from test_places();

  -- Plate P-500 sits on the bench with a buffer component in two wells.
  old_plate := register_container('plate_96', '2026-09-01 09:00', 'p:marco', 'P-500', p_into => p.bench);
  hepes := receive('vendorC:HEPES', well(old_plate, 'A1'), 50, 'volume', '2026-09-01 09:00', 'p:marco');
  perform transfer(well(old_plate, 'A1'), well(old_plate, 'A2'), hepes, 20, 'volume', '2026-09-01 09:10', 'p:marco');

  -- Someone sticks a second P-500 label on another plate while the first is still in use. Refused.
  other_plate := register_container('plate_96', '2026-09-02 09:00', 'p:marco', 'P-501', p_into => p.bench);
  perform expect_error(format('select attach_label(%s, %L, %L, %L)', other_plate, 'P-500', '2026-09-02 09:05', 'p:marco'),
                       'already on a live container', 'a second live container with barcode P-500');

  -- An import from the old system brings in a tube whose label clashes with one
  -- we already have (two labels printed from the same roll). Imports are let
  -- through, so the clash shows up instead of being lost.
  t1 := register_container('tube_1_5ml', '2026-09-03 09:00', 'p:lena', '004271', p_into => p.fridge);
  perform receive('vendorC:NACL', t1, 300, 'volume', '2026-09-03 09:00', 'p:lena');
  t2 := register_container('tube_1_5ml', '2026-09-03 10:00', 'system:import', '004271', p_into => p.fridge, p_source => 'import');
  perform receive('vendorC:NACL', t2, 200, 'volume', '2026-09-03 10:00', 'system:import', p_source => 'import');

  -- Both tubes are flagged and neither is usable until someone says which is which.
  perform expect((select count(*) from flags('2026-09-03 12:00', '2026-09-03 12:00')
                  where flag = 'barcode clash' and container_id in (t1, t2)), 2::bigint, 'clash flagged on both tubes');
  perform expect((select count(*) from usable('2026-09-03 12:00', '2026-09-03 12:00')
                  where container_id in (t1, t2) and usable = 0 and 'barcode clash' = any(reasons)), 2::bigint, 'both tubes unusable');
  -- Scanning 004271 can't pick a tube: the barcode points at two.
  perform expect((select count(*) from live_labels('2026-09-03 12:00', '2026-09-03 12:00') where barcode = '004271'),
                 2::bigint, 'containers behind barcode 004271');

  -- Plate P-500 is thrown away at the end of the month, label and all.
  perform discard(old_plate, '2026-09-30 17:00', 'p:marco');

  -- In October an old sheet of labels comes out and P-500 goes on a brand new plate. That's allowed now.
  new_plate := register_container('plate_96', '2026-10-05 09:00', 'p:marco', 'P-500', p_into => p.bench);
  perform scan(new_plate, '2026-10-05 10:00', 'p:marco', 'P-500', p.bench);

  -- The barcode now means the new plate, and the old plate stays thrown away.
  perform expect((select container_id from live_labels('2026-10-05 12:00', '2026-10-05 12:00') where barcode = 'P-500'),
                 new_plate, 'P-500 now means the new plate');
  perform expect((select status from location('2026-10-05 12:00', '2026-10-05 12:00') where container_id = old_plate),
                 'discarded', 'old plate is still thrown away');
  perform expect((select count(*) from usable('2026-10-05 12:00', '2026-10-05 12:00')
                  where container_id in (well(old_plate, 'A1'), well(old_plate, 'A2')) and 'discarded' = any(reasons) and usable = 0),
                 2::bigint, 'old plate wells still count as discarded');
  perform expect((select count(*) from flags('2026-10-05 12:00', '2026-10-05 12:00') where container_id = old_plate),
                 0::bigint, 'scanning the new plate says nothing about the old one');

  -- The label history remembers that two plates have worn P-500.
  perform expect((select count(distinct container_id) from label where barcode = 'P-500'), 2::bigint, 'plates that have worn P-500');
end $$;
rollback;

begin;
do $$
declare
  p record; src bigint; dst bigint; r bigint; lots bigint[] := '{}'; u record;
begin
  select * into p from test_places();
  insert into material (id, kind_id, name, attributes) values
    ('dna:D-1001', 'dna', 'DNA plate D-1001 designs', '{"design_id": "D-1001"}');
  insert into product (id, material_id, supplier, catalog_number) values
    ('twist:D-1001', 'dna:D-1001', 'Twist', 'D-1001');

  -- DNA plate D-1001: column 1 has 8 wells of 40 µL each. The copy plate is empty.
  src := register_container('plate_96', '2026-09-14 08:00', 'p:lena', 'D-1001', p_into => p.fridge);
  dst := register_container('plate_96', '2026-09-15 08:30', 'p:lena', 'D-1001-C', p_into => p.bench);
  for i in 1 .. 8 loop
    lots := lots || receive('twist:D-1001', well(src, chr(64 + i) || '1'), 40, 'volume', '2026-09-14 08:00', 'p:lena');
  end loop;

  -- The worklist: 5 µL from each source well into the same well of the copy plate.
  r := start_run('worklist copy', '2026-09-15 09:00', 'p:lena', p_experiment => 'EXP-150');
  insert into planned_transfer (run_id, step, from_container_id, to_container_id, lot_id, dimension, amount)
  select r, i, well(src, chr(64 + i) || '1'), well(dst, chr(64 + i) || '1'), lots[i], 'volume', 5
  from generate_series(1, 8) i;

  -- The robot log only has steps 1 to 5. A tip jam stopped it after that.
  for i in 1 .. 5 loop
    perform transfer(well(src, chr(64 + i) || '1'), well(dst, chr(64 + i) || '1'), lots[i], 5, 'volume',
                     '2026-09-15 09:00'::timestamptz + i * interval '1 minute', 'robot:hamilton-1',
                     'robot_log', r, i);
  end loop;

  -- While the run is still going, missing steps are not a problem yet.
  perform expect((select count(*) from flags('2026-09-15 09:10', 'infinity') where flag = 'robot run incomplete'),
                 0::bigint, 'no incomplete-run flag while the run is going');

  perform finish_run(r, '2026-09-15 09:30', 'robot:hamilton-1', p_outcome => 'aborted');

  -- The three steps the robot never reached show up at both ends: the source
  -- wells that may still be full, and the copy wells that may be empty.
  perform expect((select count(*) from flags('2026-09-15 10:00', 'infinity') where flag = 'robot run incomplete'),
                 6::bigint, 'steps planned but not logged, both ends');
  perform expect((select array_agg(c.position order by c.position) from flags('2026-09-15 10:00', 'infinity') f
                  join container c on c.id = f.container_id
                  where f.flag = 'robot run incomplete' and c.plate_id = dst),
                 array['F1', 'G1', 'H1'], 'copy plate wells left empty');

  -- Only the logged transfers moved liquid.
  select * into u from usable('2026-09-15 10:00', 'infinity') where container_id = well(src, 'A1');
  perform expect(u.held, 35::numeric, 'source A1 after its step ran');
  select * into u from usable('2026-09-15 10:00', 'infinity') where container_id = well(dst, 'A1');
  perform expect(u.held, 5::numeric, 'copy A1 holds 5 µL');
  perform expect(u.lot_id, lots[1], 'copy A1 holds the same DNA lot as its source');
  select * into u from usable('2026-09-15 10:00', 'infinity') where container_id = well(src, 'F1');
  perform expect(u.held, 40::numeric, 'source F1 untouched');
  perform expect((select count(*) from balances('2026-09-15 10:00', 'infinity') where container_id = well(dst, 'F1')),
                 0::bigint, 'copy F1 still empty');
  perform expect((select sum(amount) from balances('2026-09-15 10:00', 'infinity') b
                  join container c on c.id = b.container_id where c.plate_id = dst), 25::numeric, 'total in the copy plate');

  -- The log upload is retried and step 3 arrives a second time. Same run, same
  -- step: it's the same physical action, so the database refuses to count it again.
  perform expect_error(format('select transfer(%s, %s, %s, 5, %L, %L, %L, %L, %s, 3)',
                              well(src, 'C1'), well(dst, 'C1'), lots[3], 'volume', '2026-09-15 09:03', 'robot:hamilton-1', 'robot_log', r),
                       'duplicate key', 'the same robot step logged twice');
  perform expect((select amount from balances('2026-09-15 10:00', 'infinity') where container_id = well(dst, 'C1')),
                 5::numeric, 'copy C1 after the retry');

  -- Lena reruns step 6 by hand; logging it under the run fills that gap.
  perform transfer(well(src, 'F1'), well(dst, 'F1'), lots[6], 5, 'volume', '2026-09-15 11:00', 'p:lena', 'manual', r, 6);
  perform expect((select count(*) from flags('2026-09-15 12:00', 'infinity') where flag = 'robot run incomplete'),
                 4::bigint, 'steps still missing after the manual rerun');
end $$;
rollback;

begin;
do $$
declare
  p record; src bigint; dst bigint; r bigint; lots bigint[] := '{}'; u record;
begin
  select * into p from test_places();
  insert into material (id, kind_id, name, attributes) values ('dna:D-2001', 'dna', 'Designs D-2001', '{"design_id": "D-2001"}');
  insert into product (id, material_id, supplier, catalog_number) values ('twist:D-2001', 'dna:D-2001', 'Twist', 'D-2001');
  src := register_container('plate_96', '2026-09-14 08:00', 'p:lena', 'D-2001', p_into => p.fridge);
  dst := register_container('plate_96', '2026-09-15 08:30', 'p:lena', 'D-2001-C', p_into => p.bench);
  for i in 1 .. 4 loop
    lots := lots || receive('twist:D-2001', well(src, chr(64 + i) || '1'), 40, 'volume', '2026-09-14 08:00', 'p:lena');
  end loop;
  r := start_run('worklist copy', '2026-09-15 09:00', 'p:lena');
  insert into planned_transfer (run_id, step, from_container_id, to_container_id, lot_id, dimension, amount)
  select r, i, well(src, chr(64 + i) || '1'), well(dst, chr(64 + i) || '1'), lots[i], 'volume', 5
  from generate_series(1, 4) i;

  -- Steps 1, 2 and 4 are in the log. Step 3's line was lost.
  perform transfer(well(src, 'A1'), well(dst, 'A1'), lots[1], 5, 'volume', '2026-09-15 09:01', 'robot:hamilton-1', 'robot_log', r, 1);
  perform transfer(well(src, 'B1'), well(dst, 'B1'), lots[2], 5, 'volume', '2026-09-15 09:02', 'robot:hamilton-1', 'robot_log', r, 2);
  perform transfer(well(src, 'D1'), well(dst, 'D1'), lots[4], 5, 'volume', '2026-09-15 09:04', 'robot:hamilton-1', 'robot_log', r, 4);
  perform finish_run(r, '2026-09-15 09:30', 'robot:hamilton-1');

  -- Both ends of step 3 now read as if it happened, and a person is told it was assumed.
  perform expect((select held from usable('2026-09-15 10:00', 'infinity') where container_id = well(src, 'C1')), 35::numeric, 'source C1 after the assumed step');
  perform expect((select held from usable('2026-09-15 10:00', 'infinity') where container_id = well(dst, 'C1')), 5::numeric, 'copy C1 after the assumed step');
  perform expect((select count(*) from flags('2026-09-15 10:00', 'infinity') where flag = 'robot step assumed'), 1::bigint, 'assumed step flagged');
  perform expect((select source from event where run_id = r and run_step = 3), 'rule', 'the assumed step is marked as coming from a rule');

  -- The next morning the missing log line turns up (the robot PC had been
  -- offline). It replaces the assumption instead of being refused as a repeat.
  perform transfer(well(src, 'C1'), well(dst, 'C1'), lots[3], 4.5, 'volume', '2026-09-15 09:03', 'robot:hamilton-1', 'robot_log', r, 3,
                   p_recorded => '2026-09-16 08:00');
  perform expect((select held from usable('2026-09-16 10:00', 'infinity') where container_id = well(dst, 'C1')), 4.5::numeric, 'copy C1 from the real log line');
  perform expect((select count(*) from flags('2026-09-16 10:00', 'infinity') where flag = 'robot step assumed'), 0::bigint, 'flag gone once the log arrives');

  -- And on the evening of the 15th, the system said what it believed then.
  perform expect((select held from usable('2026-09-15 20:00', '2026-09-15 20:00') where container_id = well(dst, 'C1')), 5::numeric, 'copy C1 as known that evening');
end $$;
rollback;

begin;
do $$
declare
  p record; dna_plate bigint; expr bigint; mix_tube bigint; r bigint; ev bigint;
  water_bottle bigint; water_lot bigint; mix_lot bigint;
  designs text[] := array['D-0001', 'D-0002'];
  pos text; dna_lots bigint[] := '{}'; protein_lots bigint[] := '{}'; u record; x record;
begin
  select * into p from test_places();
  insert into material (id, kind_id, name, attributes)
  select 'dna:' || d, 'dna', 'DNA for design ' || d, jsonb_build_object('design_id', d) from unnest(designs) d
  union all
  select 'protein:' || d, 'sample_protein', 'Protein of design ' || d, jsonb_build_object('design_id', d) from unnest(designs) d;
  insert into product (id, material_id, supplier, catalog_number)
  select 'twist:' || d, 'dna:' || d, 'Twist', d from unnest(designs) d;

  water_bottle := register_container('bottle', '2026-09-01 09:00', 'p:lena', 'WAT-0001', p_into => p.bench);
  water_lot := receive('vendorC:WATER', water_bottle, 500000, 'volume', '2026-09-01 09:00', 'p:lena');
  mix_tube := register_container('tube_1_5ml', '2026-09-01 09:00', 'p:lena', 'MIX-0001', p_into => p.freezer);
  mix_lot := receive('vendorD:PURE', mix_tube, 1000, 'volume', '2026-09-01 09:00', 'p:lena', p_supplier_lot => 'PX-88');

  -- The DNA plate arrives dry: 2 µg of DNA per well, counted by mass.
  dna_plate := register_container('plate_96', '2026-09-14 09:00', 'p:lena', 'DNA-2001', p_into => p.freezer);
  for i in 1 .. 2 loop
    dna_lots := dna_lots || receive('twist:' || designs[i], well(dna_plate, 'A' || i), 2, 'mass', '2026-09-14 09:00', 'p:lena',
                                    p_supplier_lot => 'TW-' || designs[i]);
  end loop;

  -- Marco dissolves each well in 20 µL of water. It's the same DNA lot, now
  -- counted by volume, and he measures the concentration. There is no record
  -- function for this yet, so the test writes the lines itself.
  ev := new_event('reconstitute', '2026-09-15 09:00', 'p:marco', p_note => 'DNA dissolved in 20 µL water per well');
  for i in 1 .. 2 loop
    pos := 'A' || i;
    insert into quantity_entry (event_id, container_id, lot_id, dimension, amount, reason) values
      (ev, well(dna_plate, pos), dna_lots[i], 'mass',   -2, 'adjust'),
      (ev, well(dna_plate, pos), dna_lots[i], 'volume', 20, 'adjust'),
      (ev, water_bottle, water_lot, 'volume', -20, 'consume');
    insert into measurement (event_id, container_id, lot_id, property, value, unit)
    values (ev, well(dna_plate, pos), dna_lots[i], 'concentration', 0.1, 'ug/ul');
  end loop;

  select * into u from usable('2026-09-15 10:00', 'infinity') where container_id = well(dna_plate, 'A1');
  perform expect(u.dimension, 'volume', 'DNA is now counted by volume');
  perform expect(u.held, 20::numeric, 'DNA volume after dissolving');
  perform expect(u.lot_id, dna_lots[1], 'still the same DNA lot');
  perform expect((select count(*) from balances('2026-09-15 10:00', 'infinity') where container_id = well(dna_plate, 'A1')),
                 1::bigint, 'no dry mass left on record');

  -- Expression run: 5 µL DNA and 15 µL mix into each well, then 6 hours at 30 °C.
  expr := register_container('plate_96', '2026-09-15 10:00', 'p:marco', 'EXP-3001', p_into => p.bench);
  r := start_run('cell-free expression', '2026-09-15 10:00', 'p:marco', p_experiment => 'EXP-200');
  for i in 1 .. 2 loop
    pos := 'A' || i;
    perform transfer(well(dna_plate, pos), well(expr, pos), dna_lots[i], 5, 'volume', '2026-09-15 10:10', 'robot:hamilton-1', 'robot_log', r, i);
    perform transfer(mix_tube, well(expr, pos), mix_lot, 15, 'volume', '2026-09-15 10:20', 'robot:hamilton-1', 'robot_log', r, 10 + i);
  end loop;

  -- When expression finishes, each well's DNA and mix become one new protein lot.
  for i in 1 .. 2 loop
    pos := 'A' || i;
    protein_lots := protein_lots || make('protein:' || designs[i],
      jsonb_build_array(
        jsonb_build_object('container', well(expr, pos), 'lot', dna_lots[i], 'amount', 5),
        jsonb_build_object('container', well(expr, pos), 'lot', mix_lot, 'amount', 15)),
      well(expr, pos), 20, 'volume', '2026-09-15 16:30', 'p:marco', p_run => r, p_step => 20 + i);
  end loop;

  -- Each well now holds only its new protein lot, which is a different lot from its DNA.
  for i in 1 .. 2 loop
    pos := 'A' || i;
    perform expect((select array_agg(lot_id) from balances('2026-09-15 17:00', 'infinity') where container_id = well(expr, pos)),
                   array[protein_lots[i]], 'only protein left in well ' || pos);
    perform expect((select material_id from lot where id = protein_lots[i]), 'protein:' || designs[i], 'protein material in ' || pos);
  end loop;
  perform expect_true(protein_lots[1] <> dna_lots[1], 'protein lot is not the DNA lot');
  perform expect((select amount from balances('2026-09-15 17:00', 'infinity') where container_id = well(dna_plate, 'A1')),
                 15::numeric, 'DNA left on the DNA plate');

  -- The 14-day clock starts when the protein was made, not when the DNA arrived.
  select * into x from expiry('2026-09-15 17:00', 'infinity') where container_id = well(expr, 'A1');
  perform expect(x.expires_at, '2026-09-29 16:30'::timestamptz, 'protein expiry');
  perform expect(x.clock, 'since made', 'clock that set it');
  perform expect(x.rule_id, (select id from shelf_life_rule where material_kind_id = 'sample_protein'), 'rule that set it');
  perform expect((select reasons from usable('2026-09-30 09:00', 'infinity') where container_id = well(expr, 'A1')),
                 array['expired'], 'two weeks later');

  -- Backward lineage: the protein came from its DNA and the mix, and nothing else.
  perform expect((select array_agg(lot_id order by lot_id) from lot_ancestors(protein_lots[2], '2026-09-15 17:00') where depth = 1),
                 array[least(dna_lots[2], mix_lot), greatest(dna_lots[2], mix_lot)], 'parents of protein D-0002');
  -- Forward from the mix lot: both protein lots.
  perform expect((select count(*) from lot_descendants(mix_lot, '2026-09-15 17:00') where depth = 1), 2::bigint, 'lots made with the mix');
end $$;
rollback;

begin;
do $$
declare
  p record; t1 bigint; t2 bigint; l1 bigint; l2 bigint; buf_bottle bigint; buf bigint;
  hepes_tube bigint; nacl_tube bigint; hepes bigint; nacl bigint; plate bigint; a1 bigint; r bigint; ev bigint;
begin
  select * into p from test_places();

  -- Two deliveries of the same target, both QC'd and thawed in the fridge.
  t1 := register_container('tube_1_5ml', '2026-09-01 10:00', 'p:lena', 'TGT-0201', p_into => p.fridge);
  l1 := receive('vendorA:EGFR-100', t1, 100, 'volume', '2026-09-01 10:00', 'p:lena', p_supplier_lot => 'L1');
  t2 := register_container('tube_1_5ml', '2026-09-01 10:00', 'p:lena', 'TGT-0202', p_into => p.fridge);
  l2 := receive('vendorA:EGFR-100', t2, 100, 'volume', '2026-09-01 10:00', 'p:lena', p_supplier_lot => 'L2');
  perform qc(l1, 'pass', 'SDS-PAGE', '2026-09-02 09:00', 'p:marco');
  perform qc(l2, 'pass', 'SDS-PAGE', '2026-09-02 09:00', 'p:marco');

  -- Running buffer made from HEPES and NaCl stock.
  hepes_tube := register_container('bottle', '2026-09-01 10:00', 'p:lena', 'HEP-01', p_into => p.bench);
  hepes := receive('vendorC:HEPES', hepes_tube, 100000, 'volume', '2026-09-01 10:00', 'p:lena');
  nacl_tube := register_container('bottle', '2026-09-01 10:00', 'p:lena', 'NAC-01', p_into => p.bench);
  nacl := receive('vendorC:NACL', nacl_tube, 100000, 'volume', '2026-09-01 10:00', 'p:lena');
  buf_bottle := register_container('bottle', '2026-09-03 09:00', 'p:marco', 'RUN-01', p_into => p.bench);
  buf := make('buffer:bli-running',
              jsonb_build_array(jsonb_build_object('container', hepes_tube, 'lot', hepes, 'amount', 1000),
                                jsonb_build_object('container', nacl_tube, 'lot', nacl, 'amount', 3000)),
              buf_bottle, 100000, 'volume', '2026-09-03 09:00', 'p:marco');

  -- Lot L1 runs short, so Marco tops well A1 up from L2, then adds buffer.
  plate := register_container('plate_bli', '2026-09-04 09:00', 'p:marco', 'BLI-T-0040', p_into => p.bench);
  a1 := well(plate, 'A1');
  perform transfer(t1, a1, l1, 20, 'volume', '2026-09-04 09:05', 'p:marco');
  perform transfer(t2, a1, l2, 30, 'volume', '2026-09-04 09:06', 'p:marco');
  perform transfer(buf_bottle, a1, buf, 50, 'volume', '2026-09-04 09:07', 'p:marco');

  -- The well shows all three, nothing forced into one lot.
  perform expect((select count(*) from usable('2026-09-04 10:00', 'infinity') where container_id = a1), 3::bigint, 'rows for well A1');
  perform expect((select sum(held) from usable('2026-09-04 10:00', 'infinity') where container_id = a1), 100::numeric, 'total in well A1');
  perform expect((select held from usable('2026-09-04 10:00', 'infinity') where container_id = a1 and lot_id = l2), 30::numeric, 'L2 in well A1');

  -- The BLI run draws 10 µL from the well. We record it against each lot in the mix.
  r := start_run('BLI', '2026-09-04 11:00', 'p:marco', p_experiment => 'EXP-301');
  ev := consume(a1, l1, 2, 'volume', '2026-09-04 11:30', 'instrument:gator-1', 'robot_log', r);
  perform consume(a1, l2, 3, 'volume', '2026-09-04 11:30', 'instrument:gator-1', p_event => ev);
  perform consume(a1, buf, 5, 'volume', '2026-09-04 11:30', 'instrument:gator-1', p_event => ev);

  -- Forward trace from either target lot reaches the well and the run.
  perform expect_true(exists (
    select 1 from events_at('2026-09-05', 'infinity') e join quantity_entry q on q.event_id = e.id
    where q.lot_id in (select lot_id from lot_descendants(l1, 'infinity')) and q.amount > 0 and q.container_id = a1),
    'forward trace from L1 reaches well A1');
  perform expect_true(exists (
    select 1 from events_at('2026-09-05', 'infinity') e join quantity_entry q on q.event_id = e.id
    where q.lot_id in (select lot_id from lot_descendants(l2, 'infinity')) and q.amount > 0 and q.container_id = a1),
    'forward trace from L2 reaches well A1');

  -- Weeks later L2 fails a re-test. The run that used the mixed well is exposed to it.
  perform qc(l2, 'fail', 'SDS-PAGE re-test', '2026-09-25 09:00', 'p:marco');
  perform expect((select array_agg(distinct ru.experiment_ref)
                  from events_at('2026-09-25 10:00', 'infinity') e
                  join quantity_entry q on q.event_id = e.id
                  join run ru on ru.id = e.run_id
                  where q.lot_id in (select lot_id from lot_descendants(l2, 'infinity'))),
                 array['EXP-301'], 'experiments exposed to L2');
end $$;
rollback;

begin;
do $$
declare
  p record; stock bigint; box bigint; l bigint; kids bigint[]; mv bigint; x record;
begin
  select * into p from test_places();
  stock := register_container('tube_1_5ml', '2026-09-01 10:00', 'p:lena', 'TGT-0301', p_into => p.freezer);
  l := receive('vendorA:EGFR-100', stock, 500, 'volume', '2026-09-01 10:00', 'p:lena', p_supplier_lot => 'L4471');
  perform qc(l, 'pass', 'SDS-PAGE', '2026-09-02 09:00', 'p:marco');

  -- Thawed on the bench, split into 10 aliquots in a box, back into the -80.
  perform move(stock, p.bench, null, '2026-09-03 09:00', 'p:marco');
  box := register_container('box_9x9', '2026-09-03 09:30', 'p:marco', 'BOX-0012', p_into => p.freezer);
  kids := split(stock, l, 10, 40, 'tube_matrix', '2026-09-03 09:30', 'p:marco', 'ALQ-', p_into => box);
  perform move(stock, p.freezer, null, '2026-09-03 09:40', 'p:marco');

  perform expect((select count(*) from location('2026-09-10 12:00', 'infinity')
                  where container_id = any(kids) and path like 'Freezer F1 > %'), 10::bigint, 'all ten in the freezer');

  -- The week's binding runs need the target close at hand: the whole box goes to the fridge.
  mv := move(box, p.fridge, null, '2026-09-14 08:00', 'p:marco');
  perform expect((select count(*) from placement where event_id = mv), 1::bigint, 'one placement for the whole box');

  -- Every tube is now in the fridge, still in the same slot of the same box.
  perform expect((select count(*) from location('2026-09-14 09:00', 'infinity')
                  where container_id = any(kids) and path like 'Fridge R1 > %'), 10::bigint, 'all ten in the fridge');
  perform expect((select path from location('2026-09-14 09:00', 'infinity') where container_id = kids[4]),
                 'Fridge R1 > BOX-0012 @slot 4', 'aliquot 4 keeps its slot');

  -- Their storage condition changed with the box.
  perform expect((select count(*) from condition_stretches('infinity')
                  where container_id = any(kids) and condition = 'fridge'
                    and from_at = '2026-09-14 08:00' and to_at = 'infinity'), 10::bigint, 'tubes in fridge conditions from the move');
  perform expect((select count(*) from condition_stretches('infinity')
                  where container_id = any(kids) and condition = 'minus80' and to_at = '2026-09-14 08:00'), 10::bigint,
                 'tubes in the -80 until the move');

  -- The fridge clock for each tube starts at the move: 7 days for a thawed target.
  select * into x from expiry('2026-09-14 09:00', 'infinity') where container_id = kids[1];
  perform expect(x.expires_at, '2026-09-21 08:00'::timestamptz, 'aliquot expiry after the move');
  perform expect(x.clock, 'kept in fridge', 'clock that set it');
  perform expect((select count(*) from expiry_clocks('2026-09-14 09:00', 'infinity')
                  where container_id = any(kids) and clock = 'kept in fridge' and started_at = '2026-09-14 08:00'),
                 10::bigint, 'fridge clocks started at the move');

  -- Before the move, no fridge clock was running.
  perform expect((select count(*) from expiry_clocks('2026-09-13 09:00', 'infinity')
                  where container_id = any(kids) and clock = 'kept in fridge'), 0::bigint, 'no fridge clock before the move');

  -- One thaw before the split, one now.
  perform expect((select max(thaws) from usable('2026-09-14 09:00', 'infinity') where container_id = any(kids)), 2::bigint, 'thaws');
end $$;
rollback;

begin;
do $$
declare
  p record; f2 bigint; tube bigint; l bigint; x record;
begin
  select * into p from test_places();
  f2 := register_container('freezer', '2026-01-01', 'p:sara', p_name => 'Freezer F2', p_condition => 'minus20', p_source => 'manual');
  tube := register_container('tube_1_5ml', '2026-09-21 08:00', 'p:lena', 'T1', p_into => p.freezer);
  l := receive('vendorC:HEPES', tube, 1000, 'volume', '2026-09-21 08:00', 'p:lena');

  -- 10:00 Lena's scanner, offline, records T1 going to the bench. It doesn't sync yet.
  -- 11:00 Marco, online, scans T1 into freezer F2.
  perform move(tube, f2, null, '2026-09-21 11:00', 'p:marco');

  -- Before the sync, the record says T1 went straight from F1 to F2.
  select * into x from location('2026-09-21 10:30', '2026-09-21 12:00') where container_id = tube;
  perform expect(x.path, 'Freezer F1', 'at 10:30, as known before the sync');

  -- 13:00 the scanner comes back online and sends its 3-hour-old move.
  perform move(tube, p.bench, null, '2026-09-21 10:00', 'p:lena', p_recorded => '2026-09-21 13:00');

  -- Where is T1 now? Still F2: the late move happened before Marco's, so it can't undo it.
  select * into x from location('2026-09-21 14:00', 'infinity') where container_id = tube;
  perform expect(x.path, 'Freezer F2', 'location now');
  perform expect(x.last_confirmed_at, '2026-09-21 11:00'::timestamptz, 'last confirmed');
  perform expect(x.last_confirmed_how, 'moved with a scan', 'how it was last confirmed');

  -- But the bench hour is now part of the story: at 10:30 T1 was on the bench.
  select * into x from location('2026-09-21 10:30', 'infinity') where container_id = tube;
  perform expect(x.path, 'Bench B1', 'at 10:30, as known after the sync');
  -- And asked as of before the sync, the old answer stays what it was.
  select * into x from location('2026-09-21 10:30', '2026-09-21 12:00') where container_id = tube;
  perform expect(x.path, 'Freezer F1', 'at 10:30, as known before the sync, asked again');

  -- 15:00 Sara moves T1 to the fridge and types it in by hand, no scan. The
  -- place changes, but nobody actually confirmed it, so the last confirmation stays at 11:00.
  perform move(tube, p.fridge, null, '2026-09-21 15:00', 'p:sara', 'manual');
  select * into x from location('2026-09-21 16:00', 'infinity') where container_id = tube;
  perform expect(x.path, 'Fridge R1', 'location after the typed move');
  perform expect(x.last_confirmed_at, '2026-09-21 11:00'::timestamptz, 'a typed move is not a confirmation');
  perform expect(x.last_confirmed_how, 'moved with a scan', 'still the 11:00 scan');

  -- A scan of the tube in the fridge confirms it.
  perform scan(tube, '2026-09-21 17:00', 'p:lena', 'T1', p.fridge);
  select * into x from location('2026-09-21 18:00', 'infinity') where container_id = tube;
  perform expect(x.last_confirmed_at, '2026-09-21 17:00'::timestamptz, 'confirmed by the scan');
  perform expect(x.last_confirmed_how, 'scanned', 'how');
end $$;
rollback;

begin;
do $$
declare
  p record; water_bottle bigint; water bigint; stock bigint; gfp bigint; kids bigint[];
  lb_bottle bigint; lb bigint; x record;
  rule_gfp_made bigint; rule_gfp_fridge bigint; rule_lb bigint;
begin
  select * into p from test_places();
  select id into rule_gfp_made from shelf_life_rule where material_id = 'buffer:gfp-stock' and clock = 'since_origin';
  select id into rule_gfp_fridge from shelf_life_rule where material_id = 'buffer:gfp-stock' and clock = 'in_condition';
  select id into rule_lb from shelf_life_rule where material_id = 'buffer:loading';

  water_bottle := register_container('bottle', '2026-08-01 09:00', 'p:lena', 'WAT-0002', p_into => p.bench);
  water := receive('vendorC:WATER', water_bottle, 500000, 'volume', '2026-08-01 09:00', 'p:lena');

  -- GFP stock made on 1 August and split into two tubes kept at -80.
  stock := register_container('tube_1_5ml', '2026-08-01 10:00', 'p:marco', 'GFP-STOCK', p_into => p.freezer);
  gfp := make('buffer:gfp-stock', jsonb_build_array(jsonb_build_object('container', water_bottle, 'lot', water, 'amount', 1000)),
              stock, 1000, 'volume', '2026-08-01 10:00', 'p:marco');
  kids := split(stock, gfp, 2, 400, 'tube_1_5ml', '2026-08-01 10:30', 'p:marco', 'GFP-', p_into => p.freezer);

  -- Two months later one tube goes to the fridge to be used over the coming weeks.
  perform move(kids[1], p.fridge, null, '2026-10-01 09:00', 'p:marco');

  -- The tube in the fridge: a month from the move beats six months from making.
  select * into x from expiry('2026-10-05 12:00', 'infinity') where container_id = kids[1];
  perform expect(x.expires_at, '2026-11-01 09:00'::timestamptz, 'GFP tube in the fridge');
  perform expect(x.clock, 'kept in fridge', 'clock for the fridge tube');
  perform expect(x.rule_id, rule_gfp_fridge, 'rule for the fridge tube');

  -- The tube still in the freezer keeps the six-month date.
  select * into x from expiry('2026-10-05 12:00', 'infinity') where container_id = kids[2];
  perform expect(x.expires_at, '2027-02-01 10:00'::timestamptz, 'GFP tube in the freezer');
  perform expect(x.clock, 'since made', 'clock for the freezer tube');
  perform expect(x.rule_id, rule_gfp_made, 'rule for the freezer tube');

  -- Every clock is listed with its rule, not just the winner.
  perform expect((select array_agg(clock || ' ' || expires_at::date || ' rule ' || rule_id order by expires_at)
                  from expiry_clocks('2026-10-05 12:00', 'infinity') where container_id = kids[1]),
                 array['kept in fridge 2026-11-01 rule ' || rule_gfp_fridge, 'since made 2027-02-01 rule ' || rule_gfp_made],
                 'clocks on the fridge tube');

  -- Loading buffer made on 1 October lasts a week.
  lb_bottle := register_container('bottle', '2026-10-01 10:00', 'p:marco', 'LB-1001', p_into => p.fridge);
  lb := make('buffer:loading', jsonb_build_array(jsonb_build_object('container', water_bottle, 'lot', water, 'amount', 50000)),
             lb_bottle, 50000, 'volume', '2026-10-01 10:00', 'p:marco');
  select * into x from expiry('2026-10-05 12:00', 'infinity') where container_id = lb_bottle;
  perform expect(x.expires_at, '2026-10-08 10:00'::timestamptz, 'loading buffer expiry');
  perform expect(x.rule_id, rule_lb, 'loading buffer rule');

  -- On 5 October the buffer is fine but due soon; the GFP tube is not due yet.
  perform expect((select warnings from usable('2026-10-05 12:00', 'infinity') where container_id = lb_bottle),
                 array['expires within 14 days'], 'warning on the loading buffer');
  perform expect((select warnings from usable('2026-10-05 12:00', 'infinity') where container_id = kids[1]),
                 '{}'::text[], 'no warning on the GFP tube yet');

  -- "What expires in the next 14 days?" asked on 5 October and on 20 October.
  perform expect((select array_agg(container_id order by expires_at) from expiry('2026-10-05 12:00', 'infinity')
                  where expires_at > '2026-10-05 12:00' and expires_at <= '2026-10-19 12:00'),
                 array[lb_bottle], 'due within 14 days of 5 October');
  perform expect((select array_agg(container_id order by expires_at) from expiry('2026-10-20 12:00', 'infinity')
                  where expires_at > '2026-10-20 12:00' and expires_at <= '2026-11-03 12:00'),
                 array[kids[1]], 'due within 14 days of 20 October');

  -- By 9 October the loading buffer is expired, and by 20 October the GFP tube carries the warning.
  perform expect((select reasons from usable('2026-10-09 12:00', 'infinity') where container_id = lb_bottle),
                 array['expired'], 'loading buffer a week and a day later');
  perform expect((select warnings from usable('2026-10-20 12:00', 'infinity') where container_id = kids[1]),
                 array['expires within 14 days'], 'warning on the GFP tube');

  -- Decision D9: the fridge month is a budget of total fridge time. After 9 days
